let spelllockResolving=false;
const spelllockHitBase=hit;hit=(e,d)=>{let normal=started&&!paused&&!dead&&p.hp>0&&!spelllockResolving&&cadenceNormalAction&&classHitKind==='normal'&&!classNormalHit&&!treeExplosion&&!e?.dotTick,s=normal?activeSpelllock():null,owner=p,before=e?.hp,training=e?.trainingHits||0,eligible=s&&before>0&&enemies.includes(e)&&dist(p,e)<=160&&lineClear(p,e);let result=spelllockHitBase(e,d);if(eligible&&owner===p&&!dead&&p.hp>0&&e.hp>0&&(e.hp<before||(e.trainingHits||0)>training)&&enemies.includes(e)){s.charges--;let kind=classHitKind;classHitKind='skill';spelllockResolving=true;try{spellHit(e,s.damage*1.2,s.build);burst(e.x,e.y,40,ELEMENTS[s.build.elements[0]].color);playSignatureAudio(88,true,e.x,e.y);}finally{classHitKind=kind;spelllockResolving=false;}}return result;};
const spelllockStepBase=stepSignature;stepSignature=(s,dt)=>{if(s.mode!==88)return spelllockStepBase(s,dt);if(dead||p.hp<=0||s.owner!==p)return false;if(paused||!Number.isFinite(dt)||dt<=0)return true;s.time=Math.round((s.time+dt)*1e6)/1e6;return s.time<5&&s.charges>0;};
